// ===== 바꿀 값은 이 노드에만 있습니다 =====
const cfg = {
  githubOwner: 'YOUR-GITHUB-ID',
  githubRepo: 'invest-news-site',
  githubBranch: 'main',
  siteUrl: 'https://invest-news-site.vercel.app',
  supabaseUrl: 'https://YOUR-PROJECT.supabase.co',

  geminiModel: 'gemini-3.8-flash', // 404 no longer available이면 오류가 알려 주는 새 이름으로
  fallbackModel: 'gemini-flash-lite-latest', // 기본 모델이 3번 실패하면 사용
  embeddingModel: 'gemini-embedding-001', // 지식베이스용
  embedDim: 768, // Supabase kb_chunks.embedding 크기와 같아야 함

  discordWebhookUrl: '', // #브리핑 채널 웹훅. 비우면 알림을 건너뜀

  vaultRepo: 'invest-vault', // 옵시디안 볼트 저장소(비공개, githubOwner 계정). 비우면 노트 생성을 건너뜀
  vaultBranch: 'main',

  maxPerEdition: 90, // 한 회차에 요약할 최대 기사 수
  summaryBatch: 15, // Gemini 요약 요청 1개에 담을 기사 수
  staleHours: 72, // 이보다 오래된 미처리 기사는 요약하지 않고 건너뜀
};

// 회차 이름: 정해진 시각이면 그 이름, 수동 실행이면 실제 시각
const now = new Date();
const kst = new Date(now.getTime() + 9 * 3600_000);
const ymd = kst.toISOString().slice(0, 10);
const t = kst.getUTCHours() * 60 + kst.getUTCMinutes();
const slot = ['07:00', '12:00', '16:30', '22:00'].find((s) => {
  const m = Number(s.slice(0, 2)) * 60 + Number(s.slice(3));
  return t >= m && t - m < 30;
});
const edition = slot || kst.toISOString().slice(11, 16);

return [{ json: { ...cfg, today: ymd, edition, nowIso: now.toISOString() } }];

// Gemini 요청을 만듭니다: 분류 요청 1개 + 요약 요청 여러 개(summaryBatch건씩)
// Gemini는 기사 번호(id)로만 답하고 URL은 만들지 않습니다.
const c = $('설정').first().json;
const now = Date.parse(c.nowIso);
const fresh = $('새 기사 조회').all().map((i) => i.json).filter((r) => r && r.id);
const today = $('오늘 게시분 조회').all().map((i) => i.json).filter((r) => r && r.id);

const skipIds = [];
const usable = [];
for (const r of fresh) {
  if (now - Date.parse(r.published_at) > c.staleHours * 3600_000) skipIds.push(r.id);
  else usable.push(r);
}
usable.sort((a, b) => b.published_at.localeCompare(a.published_at));
const pick = usable.slice(0, c.maxPerEdition);
if (!pick.length) return []; // 새 기사 없음: 이번 회차는 조용히 끝남

const mk = (m) => (m === 'KR' ? '국내' : '미국·해외');
const genCfg = { responseMimeType: 'application/json', maxOutputTokens: 65536, thinkingConfig: { thinkingLevel: 'low' } };
const req = (requestId, text) => ({ requestId, body: { contents: [{ role: 'user', parts: [{ text }] }], generationConfig: genCfg } });

// ---- 분류 요청 ----
const stories = {};
for (const r of today) if (r.story_key && !stories[r.story_key]) stories[r.story_key] = r.title_ko || r.title;
const earlier = Object.entries(stories).slice(0, 150).map(([k, t]) => `${k}: ${t}`).join('\n') || '(없음)';
const list = pick.map((r) => `[${r.id}] (${mk(r.market)}) ${r.title} — ${r.source}`).join('\n');
const classifyText = `너는 한국 개인 투자자를 위한 시장 뉴스 편집자다. 아래 "새 기사"를 같은 사건끼리 묶고 중요도를 매긴 뒤, 오늘의 시장 브리핑을 써라.

규칙
- storyKey: 같은 사건이면 같은 키. 영어 소문자·숫자·하이픈 2~5단어 (예: fed-rate-hold-nov). "오늘 앞서 나온 사건"과 같은 사건이면 그 키를 그대로 써라.
- impact: 0~100. 시장 전체·주요 종목 주가에 미칠 영향과 화제성. 단순 시황 반복·홍보성 기사는 낮게.
- briefing: 4~6줄. 각 줄은 "**핵심어**: 한 문장" 형식의 한국어. 국내와 미국·해외를 고르게 다루고, 사실만 쓰며 매수·매도 권유나 예측은 쓰지 마라. URL을 쓰지 마라.
- 모든 새 기사 id를 stories에 빠짐없이 넣어라.

출력: JSON 하나만.
{"requestId":"classify","stories":[{"id":123,"storyKey":"...","impact":60}],"briefing":["**...**: ..."]}

오늘 앞서 나온 사건 (storyKey: 대표 제목)
${earlier}

새 기사
${list}`;

const out = [{ json: { ...req('classify', classifyText), meta: { pickIds: pick.map((r) => r.id), skipIds } } }];

// ---- 요약 요청 ----
for (let i = 0; i < pick.length; i += c.summaryBatch) {
  const batch = pick.slice(i, i + c.summaryBatch);
  const n = i / c.summaryBatch + 1;
  const arts = batch
    .map((r) => `[${r.id}] (${mk(r.market)}) ${r.source}: ${r.title}${r.snippet ? `\n내용: ${r.snippet}` : ''}`)
    .join('\n\n');
  const text = `너는 한국 개인 투자자를 위한 시장 뉴스 요약가다. 아래 기사마다 다음을 한국어로 작성하라.

- titleKo: 한국어 제목 (국내 기사는 원제를 다듬기만, 해외 기사는 번역). 60자 이내.
- summary: 2~3문장 요약. 기사에 있는 사실만. 내용이 제목뿐이면 제목에서 알 수 있는 것만 1문장.
- keyPoints: 투자자가 알아야 할 핵심 1~3개 (수치·일정·주체 중심). 없으면 빈 배열.
- tags: 다음 중 1~3개 [증시, 금리, 환율, 물가, 고용, 실적, 반도체, 2차전지, AI, 자동차, 바이오, 에너지, 원자재, 부동산, 정책, 규제, 무역, 지정학, 가상자산, 기업, 공모·상장]
- companies: 기사의 중심이 되는 상장 기업 (없으면 빈 배열). 국내 기업은 {"name": 한국거래소 상장 종목명(예: 삼성전자, SK하이닉스, LG에너지솔루션), "market": "KR"}, 미국 상장 기업은 {"name": 회사명, "market": "US", "ticker": 티커(예: NVDA)}. 확실하지 않으면 ticker를 빼라. 국내 종목코드는 쓰지 마라.
- sentiment: 관련 기업·시장에 우호적인 소식이면 "호재", 불리하면 "악재", 판단이 어렵거나 중립적이면 "중립". 기사 논조 분류이며 투자 의견이 아니다.
- credibility: 1~5. 공식 발표·1차 자료 인용·주요 통신사 5, 주요 언론의 사실 보도 4, 해설·전망 기사 3, 출처 불명·추측·홍보성 1~2.

규칙: 모든 기사 id에 대해 빠짐없이 답하라. URL을 쓰지 마라. 매체가 DART·SEC EDGAR·Federal Reserve인 항목은 공시·공식 발표이므로 제목에 담긴 사실만 요약하고 credibility는 5로 하라.
출력: JSON 하나만.
{"requestId":"summary-${n}","items":[{"id":123,"titleKo":"...","summary":"...","keyPoints":["..."],"tags":["..."],"companies":[{"name":"...","market":"US","ticker":"..."}],"sentiment":"중립","credibility":4}]}

기사
${arts}`;
  out.push({ json: req(`summary-${n}`, text) });
}
return out;

// 회사명 비교용 키: 대문자, (주)·법인 접미사·기호 제거. 종목 사전과 게시 워크플로가 같은 규칙을 씀
function nameKey(s) {
  let t = String(s || '').toUpperCase();
  t = t.replace(/\(주\)|㈜|주식회사|\(유\)/g, ' ').replace(/&/g, ' AND ').replace(/\/[A-Z]{2}\/?\s*$/, ' ');
  t = t.replace(/[.,'’"()\-\/:;!]/g, ' ');
  const STOP = new Set(['INC', 'INCORPORATED', 'CORP', 'CORPORATION', 'CO', 'COMPANY', 'LTD', 'LIMITED', 'PLC', 'HOLDINGS', 'HOLDING', 'GROUP', 'THE', 'CLASS', 'A', 'B', 'C', 'SA', 'NV', 'AG', 'SE', 'LLC', 'LP', 'ADR', 'DE', 'TECHNOLOGIES', 'TECHNOLOGY']);
  return t.split(/\s+/).filter((w) => w && !STOP.has(w)).join('');
}
// Gemini 응답을 읽어 분류·요약 결과를 정리하고, 종목 사전에서 찾아볼 회사명·티커를 모읍니다.
function parseJson(t) {
  t = String(t || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {} }
  return null;
}
let classify = null;
const sums = {};
let failed = 0;
for (const it of $input.all()) {
  const j = it.json || {};
  const parts = (((j.candidates || [])[0] || {}).content || {}).parts || [];
  const obj = parseJson(parts.filter((p) => !p.thought).map((p) => p.text || '').join(''));
  if (!obj) { failed++; continue; }
  if (Array.isArray(obj.stories)) classify = obj;
  if (Array.isArray(obj.items)) for (const s of obj.items) if (s && s.id !== undefined) sums[Number(s.id)] = s;
}
if (!classify && !Object.keys(sums).length) throw new Error('Gemini 요약이 모두 실패했습니다');

const keys = new Set();
const tickers = new Set();
for (const s of Object.values(sums)) {
  for (const x of Array.isArray(s.companies) ? s.companies : []) {
    if (!x || !x.name) continue;
    const k = nameKey(x.name);
    if (k) keys.add(k);
    if (x.ticker) tickers.add(String(x.ticker).toUpperCase().trim());
  }
}
return [{ json: { classify, sums, failed, keys: [...keys], tickers: [...tickers] } }];

// 회사명 비교용 키: 대문자, (주)·법인 접미사·기호 제거. 종목 사전과 게시 워크플로가 같은 규칙을 씀
function nameKey(s) {
  let t = String(s || '').toUpperCase();
  t = t.replace(/\(주\)|㈜|주식회사|\(유\)/g, ' ').replace(/&/g, ' AND ').replace(/\/[A-Z]{2}\/?\s*$/, ' ');
  t = t.replace(/[.,'’"()\-\/:;!]/g, ' ');
  const STOP = new Set(['INC', 'INCORPORATED', 'CORP', 'CORPORATION', 'CO', 'COMPANY', 'LTD', 'LIMITED', 'PLC', 'HOLDINGS', 'HOLDING', 'GROUP', 'THE', 'CLASS', 'A', 'B', 'C', 'SA', 'NV', 'AG', 'SE', 'LLC', 'LP', 'ADR', 'DE', 'TECHNOLOGIES', 'TECHNOLOGY']);
  return t.split(/\s+/).filter((w) => w && !STOP.has(w)).join('');
}
// Gemini 결과를 합쳐 기사 행, 다이제스트 Markdown, Discord 메시지, 지식베이스 조각을 만듭니다.
const c = $('설정').first().json;
const nowIso = c.nowIso;
const now = Date.parse(nowIso);
const meta = ($('프롬프트 생성').all().find((i) => i.json.requestId === 'classify') || { json: { meta: { pickIds: [], skipIds: [] } } }).json.meta;

// ---------- Gemini 결과·종목 사전 ----------
const { classify, sums, failed } = $('Gemini 결과 정리').first().json;
const ctx = $input.first().json || {};
const symbols = Array.isArray(ctx.symbols) ? ctx.symbols : [];
const watchlist = Array.isArray(ctx.watchlist) ? ctx.watchlist : [];
const watchCodes = new Set(watchlist.map((w) => `${w.market}:${w.code}`));
const watchName = Object.fromEntries(watchlist.map((w) => [`${w.market}:${w.code}`, w.name]));
const usByTicker = Object.fromEntries(symbols.filter((x) => x.market === 'US').map((x) => [x.code, x]));
const byKey = {};
for (const x of symbols) (byKey[`${x.market}:${x.name_key}`] = byKey[`${x.market}:${x.name_key}`] || x);

// Gemini가 쓴 회사명을 종목 사전과 맞춤. 사전에 없으면 코드 없이 이름만 남김
function resolve(x) {
  const market = x.market === 'US' ? 'US' : 'KR';
  const tk = x.ticker ? String(x.ticker).toUpperCase().trim() : '';
  let hit = market === 'US' && tk && usByTicker[tk] ? usByTicker[tk] : byKey[`${market}:${nameKey(x.name)}`];
  if (!hit) return { market, name: String(x.name).slice(0, 40) };
  const id = `${hit.market}:${hit.code}`;
  return { market: hit.market, code: hit.code, name: watchName[id] || (hit.market === 'KR' ? hit.name : String(x.name).slice(0, 40)) };
}
function mergeTickers(a, b) {
  const out = [];
  for (const t of [...(a || []), ...(b || [])]) {
    if (!t || !t.name) continue;
    if (out.some((o) => (t.code && o.code === t.code && o.market === t.market) || (!t.code && !o.code && o.name === t.name))) continue;
    out.push(t);
  }
  return out.slice(0, 5);
}

const storyOf = {};
for (const s of (classify && classify.stories) || []) storyOf[Number(s.id)] = s;

// ---------- 기사 행 만들기 ----------
const fresh = {};
for (const i of $('새 기사 조회').all()) if (i.json && i.json.id) fresh[i.json.id] = i.json;
const todayRows = $('오늘 게시분 조회').all().map((i) => i.json).filter((r) => r && r.id);

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const TAGS = new Set(['증시', '금리', '환율', '물가', '고용', '실적', '반도체', '2차전지', 'AI', '자동차', '바이오', '에너지', '원자재', '부동산', '정책', '규제', '무역', '지정학', '가상자산', '기업', '공모·상장']);
const TONES = new Set(['호재', '악재', '중립']);
const stripUrl = (s) => String(s || '').replace(/https?:\/\/\S+/g, '').trim();

const processed = [];
for (const id of meta.pickIds) {
  const r = fresh[id];
  if (!r) continue;
  const s = sums[id] || {};
  const st = storyOf[id] || {};
  const gemCred = Number(s.credibility) || r.source_trust;
  processed.push({
    ...r,
    status: 'published',
    title_ko: stripUrl(s.titleKo) || r.title,
    summary: stripUrl(s.summary),
    key_points: Array.isArray(s.keyPoints) ? s.keyPoints.map(stripUrl).filter(Boolean).slice(0, 3) : [],
    tags: Array.isArray(s.tags) ? s.tags.filter((t) => TAGS.has(t)).slice(0, 3) : [],
    tickers: mergeTickers(r.tickers, Array.isArray(s.companies) ? s.companies.filter((x) => x && x.name).slice(0, 4).map(resolve) : []),
    sentiment: TONES.has(s.sentiment) ? s.sentiment : '중립',
    credibility: clamp(Math.round((gemCred + r.source_trust) / 2), 1, 5),
    impact: clamp(Math.max(Number(st.impact) || 40, r.tier === 'T1' && r.impact ? r.impact : 0), 0, 100), // 공시는 규칙 영향도를 최소값으로
    story_key: (st.storyKey && String(st.storyKey).slice(0, 80)) || `a-${id}`,
    digest_date: c.today,
    edition: c.edition,
    processed_at: nowIso,
  });
}
const skipped = meta.skipIds.map((id) => fresh[id]).filter(Boolean).map((r) => ({ ...r, status: 'skipped', processed_at: nowIso }));

// ---------- 같은 사건 묶기, 점수 ----------
const all = [...todayRows.filter((r) => !meta.pickIds.includes(r.id)), ...processed];
const bySrc = {};
for (const r of all) (bySrc[r.story_key] = bySrc[r.story_key] || new Set()).add(r.source);
const BONUS = { '공시': 20, '통신사': 10, '해설': 5, '커뮤니티': 0 };
for (const r of all) {
  const cov = bySrc[r.story_key].size;
  const age = (now - Date.parse(r.published_at)) / 3600_000;
  const recency = age < 12 ? 10 : age < 24 ? 5 : 0;
  r.coverage = cov;
  const watched = (r.tickers || []).some((t) => t.code && watchCodes.has(`${t.market}:${t.code}`));
  r.importance = clamp(Math.round(0.5 * r.impact + (BONUS[r.source_grade] || 0) + 5 * Math.min(cov - 1, 4) + recency + (watched ? 15 : 0)), 0, 100);
}

// DB 저장용 (모든 행의 열을 똑같이 맞춤)
const COLS = ['url_key', 'url', 'title', 'source', 'source_trust', 'source_grade', 'tier', 'market', 'feed_kind', 'published_at', 'snippet', 'status',
  'title_ko', 'summary', 'key_points', 'tags', 'tickers', 'sentiment', 'credibility', 'impact', 'importance', 'coverage', 'story_key', 'event_type',
  'digest_date', 'edition', 'processed_at'];
const pickCols = (r) => Object.fromEntries(COLS.map((k) => [k, r[k] === undefined ? null : r[k]]));
const articleRows = [...all, ...skipped].map(pickCols);

// ---------- 다이제스트: 사건마다 대표 기사 1건 ----------
const reps = {};
for (const r of all) {
  const k = `${r.tier === 'T1' ? 'T1' : 'T2'}:${r.story_key}`; // 공시와 기사는 따로 대표를 뽑음
  const cur = reps[k];
  if (!cur || r.source_trust > cur.source_trust || (r.source_trust === cur.source_trust && r.importance > cur.importance)) reps[k] = r;
}
const items = Object.values(reps)
  .sort((a, b) => b.importance - a.importance)
  .map((r) => ({
    id: Number(r.id), tier: r.tier, market: r.market, title: r.title, titleKo: r.title_ko || r.title, source: r.source,
    sourceGrade: r.source_grade, url: r.url, publishedAt: new Date(r.published_at).toISOString(), summary: r.summary || '',
    keyPoints: r.key_points || [], tags: r.tags || [], tickers: r.tickers || [], sentiment: r.sentiment || '중립',
    credibility: r.credibility || r.source_trust, importance: r.importance, coverage: r.coverage, storyKey: r.story_key, edition: r.edition || c.edition,
    ...(r.event_type ? { eventType: r.event_type } : {}),
  }));

// ---------- 브리핑 ----------
let briefing = (classify && Array.isArray(classify.briefing) ? classify.briefing : []).map(stripUrl).filter(Boolean).slice(0, 6);
if (!briefing.length) briefing = items.slice(0, 5).map((it) => `**${it.source}**: ${it.titleKo}`);
const editions = [];
for (const i of $('오늘 브리핑 조회').all()) {
  const r = i.json;
  if (!r || !r.report_key) continue;
  const ed = r.report_key.split(':').slice(2).join(':');
  if (ed === c.edition) continue;
  let lines = [];
  try { lines = JSON.parse(r.body); } catch (e) {}
  editions.push({ edition: ed, generatedAt: new Date(r.created_at).toISOString(), briefing: lines });
}
editions.push({ edition: c.edition, generatedAt: nowIso, briefing });
editions.sort((a, b) => a.generatedAt.localeCompare(b.generatedAt));
const reportRows = [{ report_key: `briefing:${c.today}:${c.edition}`, kind: 'briefing', title: `${c.today} ${c.edition} 브리핑`, body: JSON.stringify(briefing), tickers: [], created_at: nowIso }];

// ---------- Markdown (JSON 한 줄 = YAML 한 항목) ----------
const md = [
  '---',
  `date: ${JSON.stringify(c.today)}`,
  `generatedAt: ${JSON.stringify(nowIso)}`,
  watchlist.length ? 'watchlist:' : 'watchlist: []',
  ...watchlist.map((w) => `  - ${JSON.stringify({ market: w.market, code: w.code, name: w.name })}`),
  'editions:',
  ...editions.map((e) => `  - ${JSON.stringify(e)}`),
  items.length ? 'items:' : 'items: []',
  ...items.map((it) => `  - ${JSON.stringify(it)}`),
  '---',
  '',
  ...briefing.map((l) => `- ${l}`),
  '',
].join('\n');

// UTF-8 → Base64 (Buffer 없이)
function b64(str) {
  const by = [];
  for (let i = 0; i < str.length; i++) {
    let cp = str.charCodeAt(i);
    if (cp >= 0xd800 && cp < 0xdc00 && i + 1 < str.length) {
      const lo = str.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo < 0xe000) { cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00); i++; }
    }
    if (cp < 0x80) by.push(cp);
    else if (cp < 0x800) by.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) by.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else by.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  const T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < by.length; i += 3) {
    const n = (by[i] << 16) | ((by[i + 1] || 0) << 8) | (by[i + 2] || 0);
    out += T[(n >> 18) & 63] + T[(n >> 12) & 63] + (i + 1 < by.length ? T[(n >> 6) & 63] : '=') + (i + 2 < by.length ? T[n & 63] : '=');
  }
  return out;
}

// ---------- Discord ----------
const recent = items.filter((it) => now - Date.parse(it.publishedAt) < 24 * 3600_000);
const line = (it) => `${it.sentiment === '호재' ? '🔴' : it.sentiment === '악재' ? '🔵' : '⚪'} [${it.titleKo.slice(0, 90)}](${it.url}) · ${it.source}`;
const filings = recent.filter((it) => it.tier === 'T1').slice(0, 5);
const kr = recent.filter((it) => it.tier !== 'T1' && it.market === 'KR').slice(0, 5);
const us = recent.filter((it) => it.tier !== 'T1' && it.market !== 'KR').slice(0, 5);
const embeds = [
  { title: `${c.today} ${c.edition} 시장 브리핑`, url: c.siteUrl, color: 0x14213d, description: briefing.map((l) => `• ${l}`).join('\n').slice(0, 4000) },
];
if (filings.length) embeds.push({ title: '주요 공시·공식 발표', color: 0x5b6676, description: filings.map(line).join('\n').slice(0, 4000) });
if (kr.length) embeds.push({ title: '국내 주요 뉴스', color: 0xd7263d, description: kr.map(line).join('\n').slice(0, 4000) });
if (us.length) embeds.push({ title: '미국·해외 주요 뉴스', color: 0x1b5fd1, description: us.map(line).join('\n').slice(0, 4000) });

// ---------- 지식베이스 조각 (이번 회차에 새로 요약한 기사 + 브리핑) ----------
const kbChunks = processed.map((r) => ({
  chunk_key: `article:${r.id}`,
  kind: r.tier === 'T1' ? 'filing' : 'news',
  is_ai: false,
  tier: r.tier,
  source_grade: r.source_grade,
  market: r.market,
  tickers: r.tickers,
  source: r.source,
  url: r.url,
  published_at: r.published_at,
  content: [r.title_ko, r.title !== r.title_ko ? r.title : '', r.summary, ...(r.key_points || []).map((p) => `- ${p}`), r.tags.length ? `태그: ${r.tags.join(', ')}` : '', `논조: ${r.sentiment}`]
    .filter(Boolean).join('\n').slice(0, 4000),
}));
kbChunks.push({
  chunk_key: `briefing:${c.today}:${c.edition}`, kind: 'briefing', is_ai: true, tier: null, source_grade: null, market: null, tickers: [],
  source: '시장 브리핑', url: c.siteUrl, published_at: nowIso, content: `${c.today} ${c.edition} 시장 브리핑\n${briefing.join('\n')}`,
});

return [{
  json: {
    articleRows, reportRows, kbChunks,
    noteData: { today: c.today, edition: c.edition, editions, items, watchlist },
    path: `src/content/digest/${c.today}.md`,
    content: b64(md),
    commitMessage: `digest: ${c.today} ${c.edition} (${processed.length}건)`,
    discord: { username: '투자 뉴스 브리프', embeds },
    counts: { processed: processed.length, skipped: skipped.length, items: items.length, geminiFailed: failed },
  },
}];

// 웹훅이 비어 있으면 Discord 알림을 건너뜁니다.
if (!$('설정').first().json.discordWebhookUrl) return [];
return [{ json: $('다이제스트 생성').first().json.discord }];

// 지식베이스 조각을 50개씩 묶어 Gemini 임베딩 요청을 만듭니다.
const c = $('설정').first().json;
const chunks = $('다이제스트 생성').first().json.kbChunks || [];
const out = [];
for (let i = 0; i < chunks.length; i += 50) {
  const part = chunks.slice(i, i + 50);
  out.push({
    json: {
      chunks: part,
      body: {
        requests: part.map((k) => ({
          model: `models/${c.embeddingModel}`,
          content: { parts: [{ text: k.content }] },
          taskType: 'RETRIEVAL_DOCUMENT',
          outputDimensionality: c.embedDim,
        })),
      },
    },
  });
}
return out;

// 임베딩 결과를 조각과 짝지어 저장할 행을 만듭니다. 768차원으로 줄인 벡터는 길이를 1로 맞춥니다.
const c = $('설정').first().json;
const reqs = $('지식베이스 준비').all();
function paired(item) {
  const p = item.pairedItem;
  if (Array.isArray(p)) return p[0] ? p[0].item : 0;
  return p && typeof p.item === 'number' ? p.item : 0;
}
const rows = [];
for (const it of $input.all()) {
  const req = reqs[paired(it)];
  const embs = (it.json && it.json.embeddings) || [];
  if (!req || embs.length !== req.json.chunks.length) throw new Error('임베딩 결과 개수가 요청과 다릅니다');
  req.json.chunks.forEach((k, i) => {
    const v = embs[i].values || [];
    if (v.length !== c.embedDim) throw new Error(`임베딩 크기 ${v.length} ≠ embedDim ${c.embedDim}`);
    const norm = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
    rows.push({ ...k, embedding: v.map((x) => Math.round((x / norm) * 1e6) / 1e6) });
  });
}
if (!rows.length) return [];
return [{ json: { rows } }];

// 볼트 저장소가 비어 있으면 옵시디안 노트 생성을 건너뜁니다.
if (!$('설정').first().json.vaultRepo) return [];
return [{ json: {} }];

// 옵시디안 노트를 만들어 GitHub 트리 요청으로 묶습니다 (회차당 커밋 1번).
// n8n은 "자동/" 폴더만 덮어쓰고, "종목/" 노트는 없을 때 한 번만 만듭니다.
const c = $('설정').first().json;
const { today, edition, editions, items, watchlist = [] } = $('다이제스트 생성').first().json.noteData;
const listing = $('볼트 파일 목록').first().json || {};
const parent = (($('볼트 기준 커밋').first().json || {}).object || {}).sha;
if (!listing.sha || !parent) throw new Error('볼트 저장소를 읽지 못했습니다. 저장소가 비어 있지 않은지(README로 초기화) 확인하세요.');

const paths = new Set((listing.tree || []).filter((t) => t.type === 'blob').map((t) => t.path));

// ---------- 도우미 ----------
const q = (v) => JSON.stringify(v); // YAML에서 그대로 읽히는 문자열
const safe = (s) => String(s).replace(/[\\/:*?"<>|#^[\]]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
function hash(s) { // FNV-1a → 6자리, 같은 사건 노트를 다시 찾기 위한 꼬리표
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0').slice(0, 6);
}
const kst = (iso) => new Date(Date.parse(iso) + 9 * 3600_000).toISOString().replace('T', ' ').slice(0, 16);
const mkt = (m) => (m === 'KR' ? '국내' : m === 'US' ? '미국' : '해외');
const dot = (t) => (t === '호재' ? '🔴' : t === '악재' ? '🔵' : '⚪');
const month = today.slice(0, 7);
// 종목 노트 이름: 국내는 종목명, 미국은 티커. 종목 사전에서 확인된(코드가 있는) 종목만 노트를 만듦
const noteName = (t) => (t.market === 'US' ? safe(t.code) : safe(t.name));
const coded = (list) => (list || []).filter((t) => t && t.code);
const watchSet = new Set(watchlist.map((w) => `${w.market}:${w.code}`));
const dailyName = `${today} 시장`;

// ---------- 기사 노트 (사건마다 대표 기사 1개) ----------
const files = [];
const noteOf = {};
for (const it of items) {
  const tag = hash(`${today}:${it.tier === 'T1' ? 'T1:' : ''}${it.storyKey || it.id}`); // 공시와 기사는 같은 사건이어도 노트를 따로
  const existing = [...paths].find((p) => p.startsWith(`자동/기사/${month}/`) && p.endsWith(` ~${tag}.md`));
  const path = existing || `자동/기사/${month}/${safe(it.titleKo) || '기사'} ~${tag}.md`;
  const name = path.split('/').pop().replace(/\.md$/, '');
  noteOf[it.id] = name;
  const tickers = coded(it.tickers).map((t) => `[[${noteName(t)}]]`);
  const plain = (it.tickers || []).filter((t) => !t.code).map((t) => t.name);
  const body = [
    '---',
    `날짜: ${today}`,
    `발행: ${q(kst(it.publishedAt))}`,
    `출처: ${q(it.source)}`,
    `등급: ${q(it.sourceGrade)}`,
    ...(it.eventType ? [`공시유형: ${q(it.eventType)}`] : []),
    `시장: ${q(mkt(it.market))}`,
    `논조: ${q(it.sentiment)}`,
    `중요도: ${it.importance}`,
    `신뢰도: ${it.credibility}`,
    `보도매체: ${it.coverage}`,
    `종목: ${q(tickers)}`,
    `원문: ${q(it.url)}`,
    'AI해석: false',
    `tags: ${q((it.tags || []).map((t) => t.replace(/[\s·]/g, '_')))}`,
    '---',
    '',
    `# ${it.titleKo}`,
    it.titleKo !== it.title ? `\n> ${it.title}` : '',
    '',
    it.summary || '(요약 없음)',
    '',
    ...(it.keyPoints && it.keyPoints.length ? ['## 핵심 내용', ...it.keyPoints.map((p) => `- ${p}`), ''] : []),
    `[원문 보기](${it.url})`,
    '',
    `관련: [[${dailyName}]]${tickers.length ? ' ' + tickers.join(' ') : ''}${plain.length ? ` (그 밖에 언급: ${plain.join(', ')})` : ''}`,
    '',
  ].join('\n');
  files.push({ path, content: body });
}

// ---------- 일일 노트 ----------
const row = (it) => `- ${dot(it.sentiment)} [[${noteOf[it.id]}|${it.titleKo.replace(/[|\]]/g, ' ')}]] ${it.source}, 중요도 ${it.importance}${it.coverage > 1 ? `, ${it.coverage}개 매체` : ''}`;
const filings = items.filter((it) => it.tier === 'T1');
const kr = items.filter((it) => it.tier !== 'T1' && it.market === 'KR');
const us = items.filter((it) => it.tier !== 'T1' && it.market !== 'KR');
const tickerOf = {};
for (const it of items) for (const t of coded(it.tickers)) tickerOf[noteName(t)] = t;
const allTickers = Object.keys(tickerOf);
const daily = [
  '---',
  `날짜: ${today}`,
  `마지막회차: ${q(edition)}`,
  `기사수: ${items.length}`,
  'tags: ["시장브리핑"]',
  '---',
  '',
  `# ${today} 시장`,
  '',
  '## 브리핑 (AI 요약)',
  ...[...editions].reverse().flatMap((e) => ['', `### ${e.edition}`, ...(e.briefing || []).map((l) => `- ${String(l).replace(/^[-*]\s+/, '')}`)]),
  '',
  `## 공시·공식 발표 (${filings.length})`,
  ...(filings.length ? filings.map(row) : ['- 없음']),
  '',
  `## 국내 (${kr.length})`,
  ...(kr.length ? kr.map(row) : ['- 없음']),
  '',
  `## 미국·해외 (${us.length})`,
  ...(us.length ? us.map(row) : ['- 없음']),
  '',
  ...(allTickers.length ? ['## 오늘 언급된 종목', allTickers.map((t) => `${watchSet.has(`${tickerOf[t].market}:${tickerOf[t].code}`) ? '⭐' : ''}[[${t}]]`).join(' '), ''] : []),
].join('\n');
files.push({ path: `자동/일일/${dailyName}.md`, content: daily });

// ---------- 종목 노트 (없을 때만) ----------
for (const name of allTickers) {
  const t = tickerOf[name];
  const exists = [...paths].some((p) => p.endsWith(`/${name}.md`) || p === `${name}.md`);
  if (exists) continue;
  files.push({
    path: `종목/${name}.md`,
    content: [
      '---',
      `시장: ${q(t.market === 'US' ? '미국' : '국내')}`,
      `종목코드: ${q(t.code)}`,
      `이름: ${q(t.name)}`,
      'tags: ["종목"]',
      '---',
      '',
      `# ${t.name} (${t.code})`,
      '',
      '## 최근 기사',
      '```dataview',
      'TABLE 발행, 논조, 중요도, 출처',
      'FROM "자동/기사"',
      'WHERE contains(종목, this.file.link)',
      'SORT 발행 DESC',
      'LIMIT 30',
      '```',
      '(Dataview 플러그인이 없으면 오른쪽의 백링크에서 관련 기사를 볼 수 있습니다.)',
      '',
      '## 내 메모',
      '',
    ].join('\n'),
  });
}

return [{
  json: {
    parent,
    message: `notes: ${today} ${edition} (기사 ${items.length}건)`,
    tree: { base_tree: listing.sha, tree: files.map((f) => ({ path: f.path, mode: '100644', type: 'blob', content: f.content })) },
    count: files.length,
  },
}];
